import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Qualche cenno di storia","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/ca/caa.md","filePath":"lezioni/c_analisi/ca/caa.md"}`),a={name:`lezioni/c_analisi/ca/caa.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="qualche-cenno-di-storia" tabindex="-1">Qualche cenno di storia <a class="header-anchor" href="#qualche-cenno-di-storia" aria-label="Permalink to “Qualche cenno di storia”">​</a></h1><p class="text-purple">Nella prima metà del <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1600</mn></mrow><annotation encoding="application/x-tex">1600</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1600</span></span></span></span> divenne piuttosto pericoloso occuparsi di questioni di fede: anche perché difendere le proprie idee poteva portare al rogo, quindi le menti più libere ed originali si volsero alla scienza che, essendo vera di per sé, non rendeva necessario il morire per difenderne i principi: nasce in quegli anni la fisica come disciplina autonoma, e per potersi sviluppare si rivolse all&#39;altra scienza che era già nota in quel periodo: la matematica. Però la matematica non era adatta per il mondo fisico, infatti appena la matematica veniva applicata a problemi fisici si potevano avere paradossi insolubili. Ciò rese necessario creare un tipo di matematica adatto alla fisica partendo da quella che già si conosceva e conservandone, per quanto possibile i risultati acquisiti:<br> [l&#39;Analisi Matematica o Calcolo Infinitesimale]</p><p>Il concetto di punto non è adatto al mondo fisico, infatti provate a tracciare un punto: se lo guardo con il microscopio sarà ancora un punto? evidentemente no. Se per magia diventassi piccolissimo tanto da essere più piccolo di un atomo potrei ancora pensare un punto più piccolo? evidentemente sì! Cioè il concetto base della matematica, quello di punto, che fa coppia con il concetto di numero come avrai visto in Geometria Cartesiana, è del tutto inadatto per il mondo fisico.</p>`,3)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};